INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM207MTQY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $450$ college students at a large university and finds that $37\\%$ plan to study abroad, with a margin of error of $4.5$ percentage points at $95\\%$ confidence. A second researcher surveys a random sample of $1{,}800$ students at the same university and finds that $41\\%$ plan to study abroad. Based on these two surveys, which of the following statements is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The two surveys contradict each other, so at least one must have used a flawed methodology."},{"key":"B","text":"The true percentage of students who plan to study abroad is $41\\%$ because the second survey has a larger sample."},{"key":"C","text":"The confidence interval from the first survey includes $41\\%$, so the two results are not necessarily inconsistent."},{"key":"D","text":"Because the second survey did not report a margin of error, its result cannot be compared with the first survey."}]$lyceon_json$::jsonb, 'C', NULL, E'The first survey''s $95\\%$ confidence interval is $37\\% \\pm 4.5\\%$, which spans from $32.5\\%$ to $41.5\\%$. Since $41\\%$ falls within this interval, the second survey''s result is consistent with the first survey''s range of plausible values. The two results are not necessarily inconsistent. The claim that the surveys contradict each other treats point estimates as exact, ignoring sampling variability. Saying the true percentage is $41\\%$ because of a larger sample confuses a larger sample with certainty. Saying the results cannot be compared because the second survey lacks a stated margin of error is incorrect; every random sample has a margin of error whether or not it is reported.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM215QHL1', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{7x + 11}{(x-1)(x+4)} = \\frac{A}{x-1} + \\frac{B}{x+4}$, what is the value of $A + B$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$5$"},{"key":"C","text":"$11$"},{"key":"D","text":"$\\frac{18}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $7x + 11 = A(x+4) + B(x-1)$ and substituting $x = 1$: $18 = 5A$, so $A = \\frac{18}{5}$. Substituting $x = -4$: $-17 = -5B$, so $B = \\frac{17}{5}$. Then $A + B = \\frac{18}{5} + \\frac{17}{5} = \\frac{35}{5} = 7$. The distractor $5$ comes from confusing the denominator factor used in solving for $A$ with the final answer. The distractor $11$ mistakes the constant in the numerator for the sum $A + B$. The distractor $\\frac{18}{5}$ gives only the value of $A$ alone without adding $B$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM219NCJC', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A bookshop sells hardcover books for $\\$23$ each and paperback books for $\\$9$ each. On one day, the shop sold a total of $31$ books and collected $\\$433$. How many paperback books were sold?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$14$"},{"key":"C","text":"$17$"},{"key":"D","text":"$20$"}]$lyceon_json$::jsonb, 'D', NULL, E'Let $h$ be hardcover books and $p$ be paperback books. The system is $h + p = 31$ and $23h + 9p = 433$. Substituting $h = 31 - p$ into the second equation gives $23(31 - p) + 9p = 433$, so $713 - 23p + 9p = 433$, yielding $-14p = -280$ and $p = 20$. The value $11$ is the number of hardcovers, not paperbacks, resulting from misreading what is asked. The value $14$ comes from incorrectly swapping the prices in the equation. The value $17$ arises from an arithmetic slip in simplifying $713 - 433$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21XQ22C', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the sum of the solutions of $x^2 - 13x + 36 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'By Vieta''s formulas, the sum of the solutions of $x^2 - 13x + 36 = 0$ equals $13$, the negation of the coefficient of $x$ when the leading coefficient is $1$. Alternatively, factoring gives $(x-4)(x-9) = 0$, so the solutions are $4$ and $9$, and $4 + 9 = 13$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM222OEW0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of practice sessions ($x$) and typing speed in words per minute ($y$) for $12$ participants. The least-squares regression line is $y = 2.7x + 31$. One participant had $x = 15$ practice sessions and an actual typing speed of $y = 68$ words per minute. What is the residual for this participant?', NULL, $lyceon_json$[{"key":"A","text":"$-3.5$"},{"key":"B","text":"$3.5$"},{"key":"C","text":"$71.5$"},{"key":"D","text":"$27.5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value is $2.7(15) + 31 = 40.5 + 31 = 71.5$. The residual is actual minus predicted: $68 - 71.5 = -3.5$. The value $3.5$ reverses the residual formula to predicted minus actual. The value $71.5$ is the predicted value itself, not the residual. The value $27.5$ results from computing $2.7 \\times 15 - 13 = 27.5$ or some other arithmetic error involving only part of the regression equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22Z8Q9P', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'In a circle with center $O$ and radius $19$, chord $\\overline{AB}$ has length $30$. Point $M$ is the midpoint of $\\overline{AB}$. What is the length of $\\overline{OM}$? Express your answer as a decimal to the nearest hundredth.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11.66', ARRAY['11.66'], E'Since $M$ is the midpoint of chord $\\overline{AB}$, segment $\\overline{OM}$ is perpendicular to $\\overline{AB}$. This creates a right triangle $OMA$ where $OA = 19$ (the radius), $AM = \\frac{30}{2} = 15$ (half the chord length), and $OM$ is the unknown leg. By the Pythagorean theorem: $OM^2 + AM^2 = OA^2$, so $OM^2 = 19^2 - 15^2 = 361 - 225 = 136$. Therefore $OM = \\sqrt{136} = 2\\sqrt{34} \\approx 11.6619$, which rounds to $11.66$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM231Q29K', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'The system of equations $7x + 2y = 39$ and $3x - y = 13$ has a solution $(x, y)$. What is the value of $x + y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'From the second equation, $y = 3x - 13$. Substituting into the first equation gives $7x + 2(3x - 13) = 39$, so $7x + 6x - 26 = 39$, yielding $13x = 65$ and $x = 5$. Then $y = 3(5) - 13 = 2$. Therefore $x + y = 5 + 2 = 7$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23LHZBD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $\\$130$ is on sale for $22\\%$ off. What is the sale price of the jacket?', NULL, $lyceon_json$[{"key":"A","text":"$\\$108.00$"},{"key":"B","text":"$\\$101.40$"},{"key":"C","text":"$\\$28.60$"},{"key":"D","text":"$\\$152.60$"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount is $0.22 \\times 130 = 28.60$. The sale price is $130 - 28.60 = 101.40$. The value $108.00$ comes from subtracting $22$ directly from $130$ instead of computing $22\\%$ of $130$. The value $28.60$ is the discount amount itself, not the sale price. The value $152.60$ results from adding the discount to the original price instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24VV54D', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $DEF$, $\\angle F = 90°$ and $\\sin(D) = \\frac{7}{25}$. What is $\\cos(E)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{25}$"},{"key":"B","text":"$\\frac{24}{25}$"},{"key":"C","text":"$\\frac{7}{24}$"},{"key":"D","text":"$\\frac{25}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{7}{25}$. In a right triangle with the right angle at $F$, angles $D$ and $E$ are complementary: $D + E = 90°$. The cofunction identity states that $\\cos(E) = \\sin(90° - E) = \\sin(D)$. Since $\\sin(D) = \\frac{7}{25}$, it follows that $\\cos(E) = \\frac{7}{25}$. The value $\\frac{24}{25}$ results from computing $\\cos(D)$ instead of $\\cos(E)$, confusing which angle''s cosine is requested. The value $\\frac{7}{24}$ comes from incorrectly forming a tangent ratio instead of cosine. The value $\\frac{25}{7}$ arises from inverting the fraction, confusing sine with cosecant.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24ZVT9R', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization takes a random sample of $600$ registered voters in a state and finds that $53\\%$ favor Candidate X, with a margin of error of $4.1$ percentage points at $95\\%$ confidence. A rival organization claims that a different random sample of $600$ registered voters, taken during the same period, found that only $47\\%$ favor Candidate X with the same margin of error. A journalist concludes that because $53\\%$ and $47\\%$ are on opposite sides of $50\\%$, the two polls prove the race is a toss-up. Which of the following best evaluates the journalist''s reasoning?', NULL, $lyceon_json$[{"key":"A","text":"The reasoning is valid because the average of $53\\%$ and $47\\%$ is $50\\%$."},{"key":"B","text":"The reasoning is flawed because the two confidence intervals overlap, so the data are consistent with the candidates being tied or either one leading."},{"key":"C","text":"The reasoning is valid because both polls have the same sample size and margin of error."},{"key":"D","text":"The reasoning is flawed because a sample of $600$ is too small to draw any conclusion about a statewide race."}]$lyceon_json$::jsonb, 'B', NULL, E'The first poll gives a confidence interval of $(48.9\\%, 57.1\\%)$ and the second gives $(42.9\\%, 51.1\\%)$. These intervals overlap in the range $(48.9\\%, 51.1\\%)$, meaning there exist plausible true values where the race could go either way. Because the intervals overlap, the journalist cannot conclude from these two polls alone that the race has shifted from one candidate leading to the other. Averaging the point estimates to get $50\\%$ ignores the uncertainty each poll carries. Having the same sample size and margin of error does not validate the reasoning when the intervals overlap. A sample of $600$ with a $4.1$ percentage point margin of error is a standard and adequate poll size, so sample size is not the issue.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25JDJEE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A vehicle travels $47$ miles using $2.3$ gallons of fuel on a highway and $29$ miles using $1.9$ gallons of fuel in the city. What is the vehicle''s combined fuel efficiency, in miles per gallon, for the entire trip? Round your answer to the nearest tenth.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18.1', ARRAY['18.1'], E'The total distance traveled is $47 + 29 = 76$ miles. The total fuel used is $2.3 + 1.9 = 4.2$ gallons. The combined fuel efficiency is $\\frac{76}{4.2} \\approx 18.095$, which rounds to $18.1$ miles per gallon. A common error is to average the two individual efficiencies ($\\frac{47}{2.3} \\approx 20.4$ and $\\frac{29}{1.9} \\approx 15.3$) and then take $\\frac{20.4 + 15.3}{2} \\approx 17.9$, but that incorrectly weights the two segments equally rather than by fuel consumed.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25UFGH8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'The system of equations $$y = x^2 - 4x - 7$$ $$y = 3x - 1$$ has two solutions, $(x_1, y_1)$ and $(x_2, y_2)$. What is the value of $x_1 + x_2$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Setting the equations equal: $x^2 - 4x - 7 = 3x - 1$, which simplifies to $x^2 - 7x - 6 = 0$. By Vieta''s formulas, the sum of the roots of $ax^2 + bx + c = 0$ is $-b/a$. Here $a = 1$ and $b = -7$, so $x_1 + x_2 = 7$. The discriminant is $49 + 24 = 73 > 0$, confirming two distinct real intersection points exist.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25VY4MV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A teacher records quiz scores for $9$ students: $61, 67, 71, 73, 73, 78, 82, 85, 90$. The teacher decides to add $4$ points to every student''s score. What is the range of the adjusted data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '29', ARRAY['29'], E'The range of the original data set is $90 - 61 = 29$. Adding a constant to every value shifts each score by the same amount, so the maximum becomes $94$ and the minimum becomes $65$. The range remains $94 - 65 = 29$. A common error is to think the range changes by $4$ (getting $33$) or by $2 \\times 4 = 8$ (getting $37$), misunderstanding that adding a constant to all values does not affect the spread. Another error is computing $29 + 4 = 33$, incorrectly adding the bonus to the range itself.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM267RENZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $11$ and $60$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$61$"},{"key":"B","text":"$71$"},{"key":"C","text":"$49$"},{"key":"D","text":"$3660$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $61$. By the Pythagorean theorem, the hypotenuse $c$ satisfies $c^2 = 11^2 + 60^2 = 121 + 3600 = 3721$. Taking the square root gives $c = 61$. The value $71$ results from adding the legs instead of using the theorem. The value $49$ comes from subtracting the legs. The value $3660$ mistakes the product of the legs for the hypotenuse.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM267Y19E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health researcher finds that people who drink at least $3$ cups of herbal tea per day have lower average blood pressure than people who drink no herbal tea. The study was conducted by surveying $1{,}200$ adults about their tea-drinking habits and measuring their blood pressure. Which of the following is the most appropriate conclusion from this study?', NULL, $lyceon_json$[{"key":"A","text":"Drinking herbal tea causes lower blood pressure."},{"key":"B","text":"There is an association between herbal tea consumption and lower blood pressure."},{"key":"C","text":"People should drink at least $3$ cups of herbal tea daily to lower their blood pressure."},{"key":"D","text":"Herbal tea contains compounds that reduce blood pressure."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the study is observational (surveying existing habits rather than randomly assigning tea consumption), it can establish an association but cannot establish causation. Confounding variables — such as overall healthier lifestyles among tea drinkers — could explain the difference. Claiming that herbal tea causes lower blood pressure requires a randomized controlled experiment. Recommending that people drink tea to lower blood pressure assumes both causation and a prescriptive action. Claiming that herbal tea contains blood-pressure-reducing compounds makes a mechanistic claim unsupported by a survey of habits.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26WHLKX', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $k$ is perpendicular to the line $5x - 2y = 14$ and passes through the point $(-1, 9)$. What is the equation of line $k$?', NULL, $lyceon_json$[{"key":"A","text":"$y = -\\frac{2}{5}x + \\frac{43}{5}$"},{"key":"B","text":"$y = \\frac{5}{2}x + \\frac{23}{2}$"},{"key":"C","text":"$y = -\\frac{2}{5}x + 9$"},{"key":"D","text":"$y = \\frac{2}{5}x + \\frac{47}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting $5x - 2y = 14$ in slope-intercept form: $y = \\frac{5}{2}x - 7$, so the slope is $\\frac{5}{2}$. A perpendicular line has slope $-\\frac{2}{5}$. Using point-slope form with $(-1, 9)$: $y - 9 = -\\frac{2}{5}(x + 1)$. Distributing: $y - 9 = -\\frac{2}{5}x - \\frac{2}{5}$, so $y = -\\frac{2}{5}x + 9 - \\frac{2}{5} = -\\frac{2}{5}x + \\frac{43}{5}$. The equation $y = \\frac{5}{2}x + \\frac{23}{2}$ uses the original slope instead of its negative reciprocal. The equation $y = -\\frac{2}{5}x + 9$ uses the correct slope but fails to account for the $-\\frac{2}{5}$ constant when distributing through $(x + 1)$. The equation $y = \\frac{2}{5}x + \\frac{47}{5}$ uses $\\frac{2}{5}$ instead of $-\\frac{2}{5}$, omitting the sign change for perpendicularity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2731MZ0', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A delivery service charges a flat fee of $\\$11$ plus $\\$3$ per package. A customer has a budget of at most $\\$53$ for the delivery. Which inequality represents the number of packages $p$ the customer can ship, and what is the maximum number of packages?', NULL, $lyceon_json$[{"key":"A","text":"$11 + 3p \\leq 53$; at most $14$ packages"},{"key":"B","text":"$3 + 11p \\leq 53$; at most $4$ packages"},{"key":"C","text":"$11 + 3p \\leq 53$; at most $13$ packages"},{"key":"D","text":"$11 + 3p < 53$; at most $13$ packages"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is $11 + 3p$ and must be at most $\\$53$, giving $11 + 3p \\leq 53$. Solving: $3p \\leq 42$, so $p \\leq 14$. The maximum is $14$ packages. Swapping the coefficients to get $3 + 11p \\leq 53$ is an equation setup error yielding $p \\leq 4$. Getting $13$ instead of $14$ results from rounding down after dividing $42$ by $3$ incorrectly. Using strict inequality ($<$) instead of $\\leq$ misinterprets the phrase ''at most.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
