INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM286WKRT', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9a^4b^3 - 6a^2b^5 + 12a^3b^2}{3a^2b^2}$?', NULL, $lyceon_json$[{"key":"A","text":"$3a^2b - 2b^3 + 4ab$"},{"key":"B","text":"$3a^2b - 2b^3 + 4a$"},{"key":"C","text":"$3a^2b - 6a^2b^5 + 4a$"},{"key":"D","text":"$3a^6b^5 - 2a^4b^7 + 4a^5b^4$"}]$lyceon_json$::jsonb, 'B', NULL, E'Dividing each term by $3a^2b^2$: $\\frac{9a^4b^3}{3a^2b^2} = 3a^2b$, $\\frac{-6a^2b^5}{3a^2b^2} = -2b^3$, $\\frac{12a^3b^2}{3a^2b^2} = 4a$. The result is $3a^2b - 2b^3 + 4a$. The distractor $3a^2b - 2b^3 + 4ab$ incorrectly keeps an extra factor of $b$ in the last term. The distractor $3a^2b - 6a^2b^5 + 4a$ fails to divide the middle term by $3a^2b^2$. The distractor $3a^6b^5 - 2a^4b^7 + 4a^5b^4$ multiplies exponents instead of subtracting them when dividing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28AOEHO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $250$ residents in a city found that $68\\%$ of them supported a proposed park renovation, with a margin of error of $4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $68\\%$ of all city residents support the park renovation."},{"key":"B","text":"It is plausible that the true percentage of all city residents who support the park renovation is between $64\\%$ and $72\\%$."},{"key":"C","text":"If another sample of $250$ residents is taken, exactly $68\\%$ will support the renovation."},{"key":"D","text":"Between $64\\%$ and $72\\%$ of the $250$ sampled residents support the park renovation."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error defines a plausible interval for the true population parameter. Since $68\\% \\pm 4\\%$ gives the interval from $64\\%$ to $72\\%$, it is plausible that the true percentage of all city residents who support the renovation falls in that range. The claim that exactly $68\\%$ of all residents support it treats the sample statistic as an exact population value, ignoring sampling variability. The claim that another sample will yield exactly $68\\%$ confuses the estimate with a guaranteed replication. The claim that $64\\%$ to $72\\%$ of the sampled residents support it misapplies the margin of error to the sample itself rather than to the population parameter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM294MEG7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 3 \\cdot 2^{x-1} + 5$. Which of the following correctly describes the end behavior and the horizontal asymptote of $f$?', NULL, $lyceon_json$[{"key":"A","text":"As $x \\to -\\infty$, $f(x) \\to 5$; as $x \\to \\infty$, $f(x) \\to \\infty$. The horizontal asymptote is $y = 5$."},{"key":"B","text":"As $x \\to -\\infty$, $f(x) \\to 0$; as $x \\to \\infty$, $f(x) \\to \\infty$. The horizontal asymptote is $y = 0$."},{"key":"C","text":"As $x \\to -\\infty$, $f(x) \\to 5$; as $x \\to \\infty$, $f(x) \\to \\infty$. The horizontal asymptote is $y = 3$."},{"key":"D","text":"As $x \\to -\\infty$, $f(x) \\to -\\infty$; as $x \\to \\infty$, $f(x) \\to \\infty$. There is no horizontal asymptote."}]$lyceon_json$::jsonb, 'A', NULL, E'For $f(x) = 3 \\cdot 2^{x-1} + 5$, as $x \\to -\\infty$, $2^{x-1} \\to 0$, so $f(x) \\to 3(0) + 5 = 5$. As $x \\to \\infty$, $2^{x-1} \\to \\infty$, so $f(x) \\to \\infty$. The horizontal asymptote is $y = 5$. The distractor stating the asymptote is $y = 0$ ignores the vertical shift of $+5$ and treats the function as if it had no constant term. The distractor stating the asymptote is $y = 3$ confuses the coefficient $3$ (a vertical stretch factor) with the horizontal asymptote. The distractor claiming no horizontal asymptote incorrectly treats the exponential function as having polynomial-like end behavior in both directions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29CCYB3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A committee of $3$ people is to be formed from a group of $5$ men and $4$ women. If it is known that the committee includes at least one woman, what is the probability that the committee has more women than men?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{17}{37}$"},{"key":"B","text":"$\\frac{17}{42}$"},{"key":"C","text":"$\\frac{15}{37}$"},{"key":"D","text":"$\\frac{2}{37}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of $3$-person committees from $9$ people is $\\binom{9}{3} = 84$. Committees with no women (all men) number $\\binom{5}{3} = 10$, so committees with at least one woman number $84 - 10 = 74$. Committees with more women than men require either $2$ women and $1$ man or $3$ women and $0$ men. The count of $2$-woman-$1$-man committees is $\\binom{4}{2} \\times \\binom{5}{1} = 6 \\times 5 = 30$. The count of $3$-woman committees is $\\binom{4}{3} = 4$. So $30 + 4 = 34$ committees have more women than men. The conditional probability is $\\frac{34}{74} = \\frac{17}{37}$. The distractor $\\frac{17}{42}$ uses $84$ (total committees, not restricted to at least one woman) as the denominator: $\\frac{34}{84} = \\frac{17}{42}$. The distractor $\\frac{15}{37}$ results from counting only the $2$-woman-$1$-man case as $30$ and dividing by $74$, yielding $\\frac{30}{74} = \\frac{15}{37}$, omitting the all-women committees. The distractor $\\frac{2}{37}$ results from using only the $4$ all-women committees divided by $74$, yielding $\\frac{4}{74} = \\frac{2}{37}$, omitting the $2$-woman case.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A72QIP', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'Line $m$ passes through the points $(2, -3)$ and $(8, 15)$. What is the $x$-intercept of line $m$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'The slope of line $m$ is $\\frac{15 - (-3)}{8 - 2} = \\frac{18}{6} = 3$. Using point-slope form with the point $(2, -3)$: $y - (-3) = 3(x - 2)$, which gives $y + 3 = 3x - 6$, so $y = 3x - 9$. The $x$-intercept occurs when $y = 0$: $0 = 3x - 9$, so $3x = 9$ and $x = 3$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ADRSMY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $WXY$ with the right angle at $X$, $WX = 7$ and $XY = 24$. Point $Z$ is the foot of the altitude from $X$ to hypotenuse $\\overline{WY}$. What is the length of $\\overline{XZ}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6.72', ARRAY['6.72'], E'First, find the hypotenuse $WY$ using the Pythagorean theorem: $WY = \\sqrt{7^2 + 24^2} = \\sqrt{49 + 576} = \\sqrt{625} = 25$. The area of triangle $WXY$ can be computed two ways. Using the legs: $\\text{Area} = \\frac{1}{2}(7)(24) = 84$. Using the hypotenuse as the base with altitude $XZ$: $\\text{Area} = \\frac{1}{2}(25)(XZ)$. Setting these equal: $84 = \\frac{1}{2}(25)(XZ)$, so $XZ = \\frac{168}{25} = 6.72$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BIG7W0', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A store charges a flat fee of $\\$4.50$ plus $\\$0.73$ per pound for ground coffee. A second store charges no flat fee but charges $\\$1.19$ per pound for the same coffee. For what weight, in pounds, is the total cost the same at both stores?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{450}{46}$"},{"key":"B","text":"$\\frac{450}{192}$"},{"key":"C","text":"$\\frac{119}{73}$"},{"key":"D","text":"$\\frac{45}{46}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the costs equal: $4.50 + 0.73p = 1.19p$. Subtracting $0.73p$ from both sides gives $4.50 = 0.46p$, so $p = \\frac{4.50}{0.46} = \\frac{450}{46}$. The value $\\frac{450}{192}$ results from incorrectly adding the per-pound rates ($0.73 + 1.19 = 1.92$) instead of subtracting them. The value $\\frac{119}{73}$ comes from setting the per-pound rates as a ratio without accounting for the flat fee. The value $\\frac{45}{46}$ results from a decimal-place error, using $0.45$ instead of $4.50$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BW8A33', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, point $D$ is on $\\overline{AB}$ and point $E$ is on $\\overline{AC}$ such that $\\overline{DE} \\parallel \\overline{BC}$. If $AD = 9$, $DB = 6$, and the area of triangle $ADE$ is $189$, what is the area of trapezoid $BCED$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '336', ARRAY['336'], E'Since $\\overline{DE} \\parallel \\overline{BC}$, triangles $ADE$ and $ABC$ are similar. The ratio of similarity is $\\frac{AD}{AB} = \\frac{9}{9 + 6} = \\frac{9}{15} = \\frac{3}{5}$. The ratio of areas of similar triangles equals the square of the ratio of corresponding sides, so $\\frac{\\text{Area of } \\triangle ADE}{\\text{Area of } \\triangle ABC} = \\left(\\frac{3}{5}\\right)^2 = \\frac{9}{25}$. Since the area of $\\triangle ADE = 189$, the area of $\\triangle ABC = 189 \\times \\frac{25}{9} = 525$. The area of trapezoid $BCED$ equals the area of $\\triangle ABC$ minus the area of $\\triangle ADE$: $525 - 189 = 336$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DR7SRB', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = -2(x + 3)^2 + 14$ has a maximum value. What is the maximum value of $h$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$14$"},{"key":"C","text":"$3$"},{"key":"D","text":"$-14$"}]$lyceon_json$::jsonb, 'B', NULL, E'The function $h(x) = -2(x + 3)^2 + 14$ is in vertex form $a(x - h)^2 + k$ with $a = -2$ and vertex at $(-3, 14)$. Since $a < 0$, the parabola opens downward and the vertex gives the maximum value, which is $14$. The distractor $-3$ is the $x$-coordinate of the vertex, not the maximum output value of the function. The distractor $3$ results from taking the absolute value of the $x$-coordinate of the vertex. The distractor $-14$ comes from incorrectly negating the maximum value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DU5FTO', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the equation $3x^2 - 11x + 13 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The number of real solutions is determined by the discriminant $b^2 - 4ac$. Here $a = 3$, $b = -11$, $c = 13$, so the discriminant is $(-11)^2 - 4(3)(13) = 121 - 156 = -35$. Since the discriminant is negative, the equation has no real solutions. Choosing $1$ reflects confusing a negative discriminant with the condition for a repeated root (discriminant equals zero). Choosing $2$ assumes every quadratic has two real solutions without checking the discriminant. Choosing $3$ misapplies the degree of the polynomial, which limits the maximum number of roots but does not guarantee them.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G9LAI3', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A plumber charges a service call fee plus an hourly rate. The total cost, in dollars, for $h$ hours of work is modeled by the function $C(h) = 67h + 85$. What is the best interpretation of $67$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"The plumber charges $\\$67$ for each hour of work."},{"key":"B","text":"The plumber charges a flat service call fee of $\\$67$."},{"key":"C","text":"The plumber works for $67$ hours in total."},{"key":"D","text":"The total cost for one hour of work is $\\$67$."}]$lyceon_json$::jsonb, 'A', NULL, E'In the function $C(h) = 67h + 85$, the coefficient $67$ is the rate of change — it represents the amount the total cost increases for each additional hour of work. Therefore, the plumber charges $\\$67$ per hour. The interpretation that $\\$67$ is the service call fee confuses the coefficient with the constant term; the flat fee is $\\$85$. The claim that the plumber works $67$ hours misreads the coefficient as a quantity of time rather than a rate. Saying the total cost for one hour is $\\$67$ ignores the service call fee; one hour actually costs $C(1) = 67 + 85 = 152$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GKC6GT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store marks up a product by $35\\%$ over its wholesale cost and then offers a $20\\%$ discount on the marked-up price during a sale. If the sale price of the product is $\\$75.60$, what is the wholesale cost, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '70', ARRAY['70'], E'Let $w$ be the wholesale cost. The marked-up price is $1.35w$. After a $20\\%$ discount, the sale price is $0.80 \\times 1.35w = 1.08w$. Setting $1.08w = 75.60$ gives $w = \\frac{75.60}{1.08} = 70$. A common error is to assume the markup and discount cancel to a net $15\\%$ increase, yielding $\\frac{75.60}{1.15} = 65.74$. Another error is to reverse the operations, dividing by $0.80$ first then by $1.35$, which gives the correct answer only if done properly — but students who subtract $35\\%$ then add $20\\%$ of the original ($w - 0.35w + 0.20w = 0.85w$) would get $\\frac{75.60}{0.85} \\approx 88.94$, which is incorrect.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HF82HM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 4x^2 - 9$. What is the value of $g(-3)$?', NULL, $lyceon_json$[{"key":"A","text":"$27$"},{"key":"B","text":"$-45$"},{"key":"C","text":"$-27$"},{"key":"D","text":"$45$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = -3$: $g(-3) = 4(-3)^2 - 9 = 4(9) - 9 = 36 - 9 = 27$. The distractor $-45$ results from incorrectly evaluating $(-3)^2$ as $-9$, giving $4(-9) - 9 = -36 - 9 = -45$. The distractor $-27$ comes from negating the correct answer, as if the negative input must produce a negative output. The distractor $45$ results from computing $4(9) + 9 = 36 + 9 = 45$, adding instead of subtracting the constant.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HTM1U8', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = -4x + 23$. What is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$35$"},{"key":"C","text":"$-11$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 3$: $f(3) = -4(3) + 23 = -12 + 23 = 11$. The value $35$ results from computing $4(3) + 23 = 35$, ignoring the negative sign on the coefficient. The value $-11$ results from reversing the sign of the correct answer. The value $19$ comes from computing $-4 + 23 = 19$ without multiplying $-4$ by $3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I02KSF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $7$ cm and a height of $13$ cm. What is the volume of the cylinder, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$91\\pi$"},{"key":"B","text":"$182\\pi$"},{"key":"C","text":"$637\\pi$"},{"key":"D","text":"$1274\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $637\\pi$ cubic centimeters. The volume of a cylinder is $V = \\pi r^2 h = \\pi(7)^2(13) = \\pi(49)(13) = 637\\pi$. The value $91\\pi$ results from computing $\\pi r h = \\pi(7)(13) = 91\\pi$, forgetting to square the radius. The value $182\\pi$ comes from using $2\\pi r h = 2\\pi(7)(13) = 182\\pi$, which is the lateral surface area formula rather than the volume. The value $1274\\pi$ results from incorrectly doubling the volume, perhaps confusing the formula with that of a different solid.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IWFMP9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A cone is inscribed in a hemisphere such that the base of the cone coincides with the flat circular face of the hemisphere. The hemisphere has a radius of $9$. What is the volume of the region inside the hemisphere but outside the cone? Express your answer as a decimal to the nearest tenth. (Use $\\pi \\approx 3.14159$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '763.4', ARRAY['763.4'], E'The hemisphere has radius $r = 9$. Its volume is $\\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(729) = 486\\pi$. The cone inscribed in the hemisphere has its base on the flat face, so the base radius of the cone is $9$ and the height equals the radius of the hemisphere, which is $9$. The volume of the cone is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(81)(9) = 243\\pi$. The volume of the region inside the hemisphere but outside the cone is $486\\pi - 243\\pi = 243\\pi \\approx 243 \\times 3.14159 \\approx 763.4$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IYGZ6N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers wanted to test whether a new ergonomic keyboard reduces wrist strain compared to a standard keyboard. They recruited $90$ office workers and randomly assigned $45$ to use the ergonomic keyboard and $45$ to use the standard keyboard for $8$ weeks, then measured wrist strain levels. The group using the ergonomic keyboard had significantly lower average wrist strain. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Using the ergonomic keyboard causes reduced wrist strain in office workers similar to those in the study."},{"key":"B","text":"There is an association between keyboard type and wrist strain, but no causal conclusion can be drawn."},{"key":"C","text":"The ergonomic keyboard would reduce wrist strain for all keyboard users."},{"key":"D","text":"Office workers who prefer ergonomic keyboards naturally have less wrist strain."}]$lyceon_json$::jsonb, 'A', NULL, E'Because participants were randomly assigned to treatment groups, this is a randomized controlled experiment, which supports a causal conclusion. The ergonomic keyboard can be said to cause reduced wrist strain among office workers similar to those in the study. Saying only an association exists understates the evidence; random assignment controls for confounding variables, allowing causal inference. Claiming the keyboard works for all keyboard users overgeneralizes beyond the study population of office workers. Suggesting that those who prefer ergonomic keyboards naturally have less strain describes a self-selection scenario that random assignment was designed to eliminate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JBBX7B', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3x^2(2x - 7) + 5x^2$?', NULL, $lyceon_json$[{"key":"A","text":"$6x^3 - 16x^2$"},{"key":"B","text":"$6x^3 - 21x^2$"},{"key":"C","text":"$6x^3 + 5x^2$"},{"key":"D","text":"$6x^3 - 16x$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing $3x^2$ across $(2x - 7)$ gives $6x^3 - 21x^2$. Adding $5x^2$ yields $6x^3 - 21x^2 + 5x^2 = 6x^3 - 16x^2$. The distractor $6x^3 - 21x^2$ results from forgetting to add the $5x^2$ term. The distractor $6x^3 + 5x^2$ results from dropping the $-7$ term during distribution. The distractor $6x^3 - 16x$ incorrectly reduces the exponent on $x^2$ to $x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JHO2NH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has the equation $(x + 7)^2 + (y - 3)^2 = 121$. What is the diameter of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$22$"},{"key":"C","text":"$121$"},{"key":"D","text":"$60.5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$. Here $r^2 = 121$, so $r = 11$. The diameter is $2r = 22$. The value $11$ is the radius, not the diameter — a common error of finding the radius but stopping before doubling. The value $121$ confuses $r^2$ with the diameter, treating the right-hand side of the equation as the diameter directly. The value $60.5$ results from dividing $121$ by $2$, incorrectly halving $r^2$ instead of taking the square root and then doubling.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JUJPWM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ employees at a company recorded whether each employee works remotely or in-office and whether they reported high or low job satisfaction. Of the $200$ employees, $74$ work remotely and $126$ work in-office. Among remote workers, $51$ reported high satisfaction. Among in-office workers, $63$ reported high satisfaction. If an employee who reported high satisfaction is selected at random, what is the probability that this employee works remotely?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{51}{200}$"},{"key":"B","text":"$\\frac{51}{74}$"},{"key":"C","text":"$\\frac{51}{114}$"},{"key":"D","text":"$\\frac{74}{200}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of employees with high satisfaction is $51 + 63 = 114$. Of those, $51$ work remotely. The conditional probability is $\\frac{51}{114} = \\frac{17}{38}$. The distractor $\\frac{51}{200}$ divides by the total number of employees instead of restricting to those with high satisfaction. The distractor $\\frac{51}{74}$ divides by the total number of remote workers, giving the probability of high satisfaction given remote work rather than the reverse conditional. The distractor $\\frac{74}{200}$ gives the overall proportion of remote workers regardless of satisfaction level.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K7RQ9P', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $26$. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$13\\pi$"},{"key":"B","text":"$26\\pi$"},{"key":"C","text":"$169\\pi$"},{"key":"D","text":"$676\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $26\\pi$. The circumference of a circle is $C = \\pi d = 26\\pi$. The value $13\\pi$ results from halving the diameter to get the radius and then computing $\\pi r$ instead of $\\pi d$ or $2\\pi r$. The value $169\\pi$ comes from computing $\\pi r^2 = \\pi(13)^2 = 169\\pi$, which is the area formula rather than the circumference. The value $676\\pi$ results from computing $\\pi d^2 = \\pi(26)^2$, applying an incorrect formula that squares the diameter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LE7VX1', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'A line passes through the points $(2, 9)$ and $(5, 21)$. What is the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$6$"},{"key":"D","text":"$\\frac{1}{4}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $\\frac{21 - 9}{5 - 2} = \\frac{12}{3} = 4$. The value $3$ results from computing the denominator correctly but making an arithmetic error in the numerator (e.g., getting $9$ instead of $12$). The value $6$ comes from using only the $y$-coordinates ($\\frac{21 - 9}{2} = 6$) instead of the correct slope formula. The value $\\frac{1}{4}$ results from inverting the slope formula to $\\frac{\\Delta x}{\\Delta y}$ instead of $\\frac{\\Delta y}{\\Delta x}$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LP8QJA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A machine produces $174$ bolts in $6$ minutes. At this constant rate, how many bolts does the machine produce in $25$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$725$"},{"key":"B","text":"$700$"},{"key":"C","text":"$750$"},{"key":"D","text":"$1044$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate is $\\frac{174}{6} = 29$ bolts per minute. In $25$ minutes, the machine produces $29 \\times 25 = 725$ bolts. The value $700$ results from rounding the rate to $28$ bolts per minute and multiplying by $25$. The value $750$ comes from rounding the rate to $30$ bolts per minute. The value $1044$ results from multiplying $174 \\times 6 = 1044$, incorrectly multiplying the given values instead of finding the unit rate and scaling.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M43UKQ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'The system of inequalities $2x + 5y \\leq 40$ and $x \\geq 3$ defines a region in the $xy$-plane. What is the maximum integer value of $y$ for points $(x, y)$ in this region when $x = 7$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Substituting $x = 7$ into $2x + 5y \\leq 40$ gives $14 + 5y \\leq 40$, so $5y \\leq 26$, meaning $y \\leq 5.2$. Since $7 \\geq 3$, the constraint $x \\geq 3$ is satisfied. The maximum integer value of $y$ is $5$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NRIK50', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A town''s population was $14{,}700$ in 2018 and $16{,}611$ in 2022. What is the percent increase in the town''s population from 2018 to 2022, rounded to the nearest tenth of a percent?', NULL, $lyceon_json$[{"key":"A","text":"$13.0\\%$"},{"key":"B","text":"$11.5\\%$"},{"key":"C","text":"$1{,}911\\%$"},{"key":"D","text":"$88.5\\%$"}]$lyceon_json$::jsonb, 'A', NULL, E'The increase is $16{,}611 - 14{,}700 = 1{,}911$. The percent increase is $\\frac{1{,}911}{14{,}700} \\times 100 \\approx 13.0\\%$. The value $11.5\\%$ results from dividing the increase by the 2022 population ($\\frac{1{,}911}{16{,}611}$) instead of the 2018 population. The value $1{,}911\\%$ confuses the absolute change with a percentage. The value $88.5\\%$ comes from computing $\\frac{14{,}700}{16{,}611} \\times 100$, which gives the ratio of old to new rather than the percent increase.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O3PSGP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a relationship between hours of sunlight per day ($x$) and daily ice cream sales in dollars ($y$). The line of best fit is $y = 41x - 87$. What does the slope of the line represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of sunlight, daily ice cream sales increase by approximately $\\$41$."},{"key":"B","text":"For each additional dollar of ice cream sold, the hours of sunlight increase by approximately $41$."},{"key":"C","text":"When there are $0$ hours of sunlight, daily ice cream sales are $-\\$87$."},{"key":"D","text":"Daily ice cream sales are approximately $41$ times the hours of sunlight."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of $41$ means that for each $1$-unit increase in $x$ (hours of sunlight), $y$ (daily ice cream sales) increases by $\\$41$. The claim that hours of sunlight increase by $41$ per dollar reverses the roles of the independent and dependent variables. The interpretation involving $0$ hours of sunlight describes the $y$-intercept ($-87$), not the slope. The claim that sales are $41$ times the sunlight ignores the $y$-intercept and mischaracterizes a linear relationship as a direct proportion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ORZR6T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages of $8$ participants in a workshop are $21, 24, 26, 27, 31, 33, 38, 52$. If the outlier $52$ is removed from the data set, which of the following statements correctly describes the effect on the mean and median?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and median decrease."},{"key":"B","text":"The mean decreases and the median stays the same."},{"key":"C","text":"The mean stays the same and the median decreases."},{"key":"D","text":"Both the mean and median increase."}]$lyceon_json$::jsonb, 'A', NULL, E'With all $8$ values, the mean is $\\frac{252}{8} = 31.5$ and the median is $\\frac{27 + 31}{2} = 29$. After removing $52$, the $7$ remaining values are $21, 24, 26, 27, 31, 33, 38$. The new mean is $\\frac{200}{7} \\approx 28.57$ (decreased) and the new median is $27$ (decreased from $29$). The claim that only the mean decreases while the median stays the same fails because the median shifts from the average of the $4$th and $5$th values to the $4$th value alone. The claim that the mean stays the same ignores that removing the highest value always reduces the mean. The claim that both increase contradicts the removal of a value larger than the original mean.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P8LZHE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values $11, 14, 14, 17, 19, 23, 29$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$17$"},{"key":"C","text":"$18.14$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'B', NULL, E'The data set has $7$ values in ascending order. The median is the $4$th value, which is $17$. The value $14$ is the mode (the most frequently occurring value), not the median. The value $18.14$ is approximately the mean ($\\frac{127}{7} \\approx 18.14$), not the median. The value $19$ is the $5$th value, which would result from counting incorrectly to the middle position.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QNSWF6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, side $\\overline{QR}$ is extended through $R$ to point $S$. If $\\angle P = 47°$ and $\\angle Q = 68°$, what is the measure, in degrees, of exterior angle $\\angle PRS$?', NULL, $lyceon_json$[{"key":"A","text":"$65°$"},{"key":"B","text":"$112°$"},{"key":"C","text":"$115°$"},{"key":"D","text":"$133°$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $115°$. By the Exterior Angle Theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles: $\\angle PRS = \\angle P + \\angle Q = 47° + 68° = 115°$. The value $65°$ results from finding the interior angle at $R$ ($180° - 47° - 68° = 65°$) and stopping there without computing the exterior angle. The value $112°$ comes from an arithmetic error when adding $47°$ and $68°$. The value $133°$ comes from incorrectly subtracting $47°$ from $180°$, treating the problem as a supplementary angle calculation with only one remote interior angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RKH4LI', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $w$ in the equation $7w - 19 = 30$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$\\frac{11}{7}$"},{"key":"C","text":"$\\frac{30}{7}$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding $19$ to both sides gives $7w = 49$, and dividing both sides by $7$ gives $w = 7$. The value $\\frac{11}{7}$ results from subtracting $19$ from $30$ to get $11$ and then dividing by $7$, failing to move the constant to the right side correctly. The value $\\frac{30}{7}$ comes from dividing $30$ by $7$ without first adding $19$ to both sides. Choosing $-7$ results from a sign error when isolating the variable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RMILUX', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $\\frac{4x - 9}{5} + 3 = x - 2$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '16', ARRAY['16'], E'Multiply both sides of the equation by $5$ to eliminate the fraction: $4x - 9 + 15 = 5x - 10$. Combine like terms on the left: $4x + 6 = 5x - 10$. Subtract $4x$ from both sides: $6 = x - 10$. Add $10$ to both sides: $x = 16$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S5WUOH', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'A linear function $g$ satisfies $g(2) = 17$ and $g(9) = -18$. What is the value of $g(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '27', ARRAY['27'], E'The rate of change (slope) of $g$ is $\\frac{-18 - 17}{9 - 2} = \\frac{-35}{7} = -5$. Using the point $(2, 17)$: $g(x) = -5(x - 2) + 17 = -5x + 10 + 17 = -5x + 27$. Therefore $g(0) = -5(0) + 27 = 27$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SSMW3B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $37°$ and the measure of angle $Q$ is $84°$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$59°$"},{"key":"B","text":"$49°$"},{"key":"C","text":"$121°$"},{"key":"D","text":"$69°$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of interior angles in a triangle is $180°$. Therefore angle $R = 180° - 37° - 84° = 59°$. The value $49°$ results from an arithmetic slip when subtracting (e.g., computing $180 - 37 - 84$ as $180 - 131 = 49$ by miscalculating $37 + 84$). The value $121°$ comes from finding $37° + 84° = 121°$ but forgetting to subtract from $180°$, reporting the sum of the other two angles instead of the missing angle. The value $69°$ results from a different subtraction error such as computing $180 - 84 - 37$ as $96 - 37 = 69$ by miscalculating $180 - 84$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V2KFFW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university studied whether participating in undergraduate research improves graduation rates. Faculty advisors selected $120$ students they considered highly motivated and enrolled them in a research program; $120$ other students who did not participate served as the comparison group. After four years, $93\\%$ of research participants graduated compared to $79\\%$ of the comparison group. A university administrator concludes that the research program caused the higher graduation rate. Which of the following best identifies a flaw in the administrator''s conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of $240$ students is too small for any meaningful conclusion."},{"key":"B","text":"Students were not randomly assigned to the groups; faculty advisors selected students they considered highly motivated, so pre-existing motivation differences could explain the higher graduation rate."},{"key":"C","text":"The study should have measured grade point average instead of graduation rate."},{"key":"D","text":"A $14$-percentage-point difference is not large enough to be statistically significant."}]$lyceon_json$::jsonb, 'B', NULL, E'The critical flaw is the lack of random assignment. Faculty advisors selected students they judged to be highly motivated, introducing selection bias. The research group may have graduated at a higher rate due to their pre-existing motivation rather than the research experience itself. Without random assignment, causation cannot be established. Claiming the sample is too small is unsupported — $240$ is a reasonable sample for comparing proportions. Suggesting GPA should replace graduation rate as the outcome measure does not address the causal reasoning flaw. Claiming the $14$-point difference is too small to be significant is a statistical assertion requiring a formal test; regardless, the design flaw of non-random assignment is the primary issue preventing a causal conclusion.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VAF4KB', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $7x - 19 > 2$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$2$"},{"key":"C","text":"$3$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'D', NULL, E'Solving $7x - 19 > 2$ gives $7x > 21$, so $x > 3$. Only $x = 4$ satisfies this strict inequality. Substituting $x = 3$ gives $7(3) - 19 = 2$, which equals $2$ but is not strictly greater, so it fails. The values $1$ and $2$ both produce results less than $2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X992SE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist models the relationship between water temperature in degrees Celsius ($x$) and dissolved oxygen concentration in mg/L ($y$) in a lake using the equation $y = -0.19x + 13.4$, where $5 \\leq x \\leq 35$. The correlation coefficient is $r = -0.94$. Which of the following is the best interpretation of these results?', NULL, $lyceon_json$[{"key":"A","text":"There is a strong negative linear association between water temperature and dissolved oxygen; for each $1°\\text{C}$ increase in temperature, dissolved oxygen decreases by approximately $0.19$ mg/L."},{"key":"B","text":"Increasing water temperature causes dissolved oxygen concentration to decrease by $0.19$ mg/L per degree Celsius."},{"key":"C","text":"Approximately $94\\%$ of the variation in dissolved oxygen is explained by the linear relationship with temperature."},{"key":"D","text":"For each $1$ mg/L decrease in dissolved oxygen, water temperature increases by approximately $0.19°\\text{C}$."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of $-0.19$ indicates that for each $1°\\text{C}$ increase in temperature, dissolved oxygen decreases by about $0.19$ mg/L, and $r = -0.94$ confirms a strong negative linear association. The claim that temperature causes the decrease is not supported because correlation does not imply causation. The statement that $94\\%$ of the variation is explained confuses $r$ with $r^2$; in fact, $r^2 \\approx 0.8836$, meaning about $88.4\\%$ of the variation is explained. The claim that temperature increases by $0.19°\\text{C}$ per $1$ mg/L decrease in dissolved oxygen reverses the slope interpretation — $\\frac{1}{0.19} \\approx 5.26$ would be the correct reciprocal rate if the roles were swapped.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XCC44M', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $17$ feet and a width of $11$ feet. What is the area of the garden, in square feet?', NULL, $lyceon_json$[{"key":"A","text":"$56$"},{"key":"B","text":"$143$"},{"key":"C","text":"$187$"},{"key":"D","text":"$289$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $187$ square feet. The area of a rectangle is length times width: $17 \\times 11 = 187$. The value $56$ results from computing the perimeter $2(17 + 11) = 56$ instead of the area, confusing the two formulas. The value $143$ comes from an arithmetic slip such as computing $13 \\times 11$ instead of $17 \\times 11$. The value $289$ results from squaring $17$ instead of multiplying $17$ by $11$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z03QSE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $11$ red marbles, $7$ blue marbles, and $3$ green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{21}$"},{"key":"B","text":"$\\frac{7}{18}$"},{"key":"C","text":"$\\frac{7}{14}$"},{"key":"D","text":"$\\frac{3}{21}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is $11 + 7 + 3 = 21$. The probability of selecting a blue marble is $\\frac{7}{21}$, which simplifies to $\\frac{1}{3}$. The distractor $\\frac{7}{18}$ results from omitting the green marbles when counting the total ($11 + 7 = 18$). The distractor $\\frac{7}{14}$ results from miscounting the total as $14$. The distractor $\\frac{3}{21}$ gives the probability of selecting a green marble instead of a blue one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZT8QFA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A solution is prepared by mixing $7$ grams of salt with $3$ liters of water. A chemist needs to prepare $11$ liters of this solution at the same concentration. How many grams of salt are needed for the $11$-liter batch, rounded to the nearest tenth?', NULL, $lyceon_json$[{"key":"A","text":"$25.7$"},{"key":"B","text":"$23.1$"},{"key":"C","text":"$33.0$"},{"key":"D","text":"$4.7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The concentration is $\\frac{7}{3}$ grams per liter. For $11$ liters: $\\frac{7}{3} \\times 11 = \\frac{77}{3} \\approx 25.7$ grams. The value $23.1$ results from using the ratio $\\frac{7}{3}$ incorrectly as $\\frac{7}{3+7} \\times 11 \\times 3 = 23.1$. The value $33.0$ comes from incorrectly multiplying $3 \\times 11 = 33$ and confusing liters with grams. The value $4.7$ results from dividing $\\frac{7 \\times 3}{11} \\approx 1.91$ and further misapplying the proportion by computing $\\frac{7}{11} \\times \\frac{11}{3+11}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW209UTD0', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the Svalbard Glacier Observatory have measured a 14% reduction in ice thickness across the Nordenskiöld glacier since 2017. _______ satellite imagery from the same period reveals that the glacier''s terminal edge has retreated by nearly 900 meters, reinforcing concerns about the pace of Arctic ice loss.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"Consequently,"},{"key":"D","text":"On the other hand,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "Similarly," which signals that a parallel finding from a different data source supports the same conclusion. The first sentence presents ground-based measurements showing reduced ice thickness, and the second sentence presents satellite data showing the glacier''s terminal retreat — two analogous observations pointing in the same direction. "For instance" would indicate that the satellite data is an example of the ice thickness measurement, but the retreat of the terminal edge is a distinct phenomenon, not a specific instance of thickness reduction. "Consequently" implies that the satellite observation is a direct result of the thickness reduction, but both are parallel indicators of ice loss rather than cause and effect. "On the other hand" signals contrast, yet both findings converge on the same conclusion about accelerating ice loss.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20DD83L', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Geochemist Lena Björk analyzed strontium isotope ratios in the tooth enamel of 53 medieval skeletons excavated from a churchyard on the Swedish island of Gotland. Because strontium isotope signatures in tooth enamel reflect the geological substrate of the region where an individual lived during childhood, they can indicate whether a person grew up locally or migrated from elsewhere. Björk found that 29 of the 53 individuals displayed strontium signatures inconsistent with Gotland''s limestone bedrock but consistent with the granitic terrains of mainland Scandinavia. Notably, these 29 nonlocal individuals were buried in the same section of the churchyard, clustered around a stone chapel that parish records identify as having been funded by a guild of mainland merchants active on Gotland during the thirteenth century. Björk argues that this spatial patterning suggests ________', $lyceon_json$[{"key":"A","text":"the guild maintained a distinct burial zone for its members and their families, indicating that mainland migrants preserved a separate communal identity even in death."},{"key":"B","text":"Gotland's limestone bedrock underwent a geochemical change during the medieval period that altered local strontium isotope signatures."},{"key":"C","text":"the 29 nonlocal individuals all arrived on Gotland simultaneously as part of a single large-scale migration event in the thirteenth century."},{"key":"D","text":"parish records from medieval Gotland are unreliable as historical sources because they contradict the geochemical evidence from tooth enamel analysis."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage connects three facts: nonlocal strontium signatures, clustering around a chapel funded by a mainland merchant guild, and spatial separation within the churchyard. The most logical inference is that the guild maintained a dedicated burial area, reflecting a preserved communal identity among mainland migrants. The choice about geochemical change in bedrock is unsupported and would undermine the entire analytical method rather than explain the spatial pattern. The choice about a single migration event goes beyond the evidence; the passage identifies a guild active over a period, not a one-time event, and strontium data alone cannot establish simultaneous arrival. The choice about unreliable parish records misreads the passage — the records and the geochemical evidence are consistent with each other, not contradictory, since the chapel funder matches the nonlocal burials.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21YZX01', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the archaeologists uncovered the burial site in northern Jordan, they discovered that the ceramic vessels _______ in a geometric pattern unlike anything previously documented in the region''s archaeological record.', $lyceon_json$[{"key":"A","text":"have been arranged"},{"key":"B","text":"had been arranged"},{"key":"C","text":"are being arranged"},{"key":"D","text":"were being arranging"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence describes a discovery made in the past ("uncovered," "discovered") about an action — the arrangement of the vessels — that occurred even earlier, before the discovery itself. The past perfect passive "had been arranged" correctly conveys that the arranging was completed before the past-tense discovery. "Have been arranged" uses the present perfect, which indicates a connection to the present and conflicts with the established past-tense narrative frame. "Are being arranged" is present progressive passive, which implies the arranging is happening at the time of speaking, not before the discovery. "Were being arranging" is ungrammatical because it incorrectly pairs the passive auxiliary "being" with the present participle "arranging" rather than a past participle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23DZ0GY', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the lead violinist nor the three cellists in the chamber ensemble _______ willing to perform the commissioned piece without additional rehearsal time, a stance that the ensemble''s director reluctantly accepted after reviewing the score''s technical demands.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"is"},{"key":"C","text":"were"},{"key":"D","text":"has been"}]$lyceon_json$::jsonb, 'C', NULL, E'In a "neither...nor" construction, the verb agrees with the subject nearest to it. The nearest subject is "the three cellists," which is plural, so the verb must be plural as well. "Were" is the plural past-tense form that agrees with "cellists" and matches the past-tense narrative established by "accepted." "Was" is singular and would agree with "violinist" but not with the nearer plural subject "cellists." "Is" is singular present tense, failing both in number agreement with "cellists" and in tense consistency with the past-tense context. "Has been" is singular present perfect, which similarly fails in number and tense.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW256BE8R', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Frustrated by decades of inconclusive results from laboratory simulations, _______ instead of replicating deep-sea pressure conditions artificially, they lowered instrumented capsules directly onto hydrothermal vents along the Mid-Atlantic Ridge.', $lyceon_json$[{"key":"A","text":"a radically different methodology was proposed by the geophysicists:"},{"key":"B","text":"the geophysicists proposed a radically different methodology:"},{"key":"C","text":"it was proposed by the geophysicists to adopt a radically different methodology:"},{"key":"D","text":"the geophysicists' radically different methodology, proposing"}]$lyceon_json$::jsonb, 'B', NULL, E'The introductory participial phrase "Frustrated by decades of inconclusive results from laboratory simulations" must be followed immediately by the noun it modifies. The geophysicists are the ones who were frustrated, so "the geophysicists" must appear as the subject right after the comma. "The geophysicists proposed a radically different methodology" places the correct subject immediately after the modifying phrase, producing a grammatically sound sentence. The choice beginning with "a radically different methodology was proposed" creates a dangling modifier because "methodology" — not the geophysicists — appears as the grammatical subject after the participial phrase, illogically suggesting that a methodology was frustrated. The choice beginning with "it was proposed" uses an expletive construction that separates the modifier from its logical subject, creating a dangling modifier. The choice ending with "proposing" lacks a finite verb for the main clause and produces an incomplete sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25JSFU2', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Architect Lina Matsuda designed a concert hall in which the curved interior walls channel sound waves toward every seat with equal _______ acoustic engineers had long considered such uniform distribution impractical for venues seating more than three thousand patrons.', $lyceon_json$[{"key":"A","text":"intensity;"},{"key":"B","text":"intensity,"},{"key":"C","text":"intensity"},{"key":"D","text":"intensity:"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct punctuation is a semicolon after "intensity." The sentence contains two independent clauses: "the curved interior walls channel sound waves toward every seat with equal intensity" and "acoustic engineers had long considered such uniform distribution impractical for venues seating more than three thousand patrons." A semicolon correctly joins two independent clauses without a coordinating conjunction. A comma would create a comma splice. Omitting punctuation would create a run-on sentence. A colon is inappropriate because the second clause does not explain or define "intensity."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26GT25S', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While writing a proposal for a university research committee, a student wants to argue that a particular conservation method deserves further investment despite its limitations. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26QPJCA', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Entomologist Yuki Harada studied carpenter bee nesting behavior in bamboo groves near Kumamoto, Japan. She observed that female carpenter bees always excavated new tunnels from the bottom node of a bamboo segment upward, despite the fact that boring downward would require less effort due to gravity assisting the removal of wood shavings. Harada noted that water readily pools inside bamboo internodes after rain, accumulating at the lowest point. Given this observation, the bees'' preference for upward excavation most likely ________', $lyceon_json$[{"key":"A","text":"reduces the risk that rainwater will flood the nest chamber, since the entrance sits below the brood cells."},{"key":"B","text":"allows the bees to construct longer tunnels than would be possible by boring downward."},{"key":"C","text":"results from the bees' inability to detect the orientation of bamboo segments before beginning excavation."},{"key":"D","text":"reflects a learned behavior that older bees teach to younger bees through direct demonstration."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that water pools at the lowest point of bamboo internodes. Boring upward from the bottom means the entrance is at the low point and brood cells sit higher, so rainwater entering the segment would drain out the entrance rather than flood the nest. This logically connects the two observations. The choice about longer tunnels is unsupported; the passage gives no indication that direction affects tunnel length. The choice about inability to detect orientation contradicts the passage, which shows the bees consistently choose the bottom node, indicating they can detect orientation. The choice about learned behavior introduces a social-learning claim with no support in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW291D4TR', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in the context of the passage as a whole?', E'Literary scholars have long debated whether the unreliable narrator in Kazuo Ishiguro''s The Remains of the Day serves primarily as a psychological portrait or as a political commentary. Those who favor the psychological reading point to Stevens''s systematic suppression of emotional memory, arguing that his stilted narration enacts the mechanisms of repressive self-deception rather than addressing any external social order.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29KC4NO', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists at the Hainan Tropical Ocean Institute hypothesized that parrotfish in heavily fished reefs compensate for reduced competition by expanding their grazing territory. In unfished control reefs, individual parrotfish typically forage within a 14-square-meter patch and maintain stable body mass throughout the dry season. The researchers predicted that on fished reefs, where competing herbivorous fish have been removed, individual parrotfish would patrol significantly larger areas and exhibit higher seasonal weight gain.', $lyceon_json$[{"key":"A","text":"Parrotfish on fished reefs were observed grazing across 31-square-meter patches on average and gained 18 percent more mass during the dry season than parrotfish on control reefs."},{"key":"B","text":"The total number of parrotfish species was lower on fished reefs than on unfished reefs across all survey sites."},{"key":"C","text":"Algal cover on fished reefs was significantly higher than on control reefs despite the presence of parrotfish."},{"key":"D","text":"Parrotfish on control reefs showed no significant change in grazing territory size over a three-year monitoring period."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis predicts that parrotfish on fished reefs will patrol larger areas and gain more weight. The finding that parrotfish on fished reefs grazed across 31-square-meter patches (versus 14 on control reefs) and gained 18 percent more mass directly confirms both predictions. The finding about fewer parrotfish species on fished reefs addresses species diversity, not individual territory expansion or weight gain. The finding about higher algal cover would actually undermine the hypothesis by suggesting parrotfish are not grazing more effectively. The finding about stable territory size on control reefs describes the baseline but does not address the key prediction about fished reefs.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A7Z4ZT', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Although the novelist Ismail Kadare drew extensively on Albanian folklore, his retellings were never _______ reproductions of oral tradition. Instead, he restructured inherited narratives to foreground political allegory, recasting familiar tales so that they addressed the mechanisms of authoritarian control.', $lyceon_json$[{"key":"A","text":"slavish"},{"key":"B","text":"tangential"},{"key":"C","text":"illicit"},{"key":"D","text":"provisional"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts Kadare''s use of folklore with what his retellings were not: mere copying. The word "slavish" means excessively imitative or showing no originality, which precisely fits the contrast with the subsequent sentence explaining that he actively restructured the narratives. "Tangential" means only marginally connected to the subject, which would imply the retellings barely related to oral tradition — the opposite of what the passage describes, since it says he drew extensively on folklore. "Illicit" means forbidden by law or rules, which introduces a legal dimension entirely absent from the passage''s discussion of literary method. "Provisional" means arranged temporarily or subject to later change, which addresses the permanence of the retellings rather than whether they were original or imitative, making it irrelevant to the contrast the passage establishes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AL1Q81', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While writing an article about urban ecology, a student wants to emphasize the surprising nature of a recent finding about peregrine falcons. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AXUGXV', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, geochemist Clair Patterson published findings demonstrating that industrial lead contamination had infiltrated virtually every ecosystem on _______ research ultimately prompted the United States government to ban lead additives in gasoline.', $lyceon_json$[{"key":"A","text":"Earth, his"},{"key":"B","text":"Earth. His"},{"key":"C","text":"Earth his"},{"key":"D","text":"Earth; and his"}]$lyceon_json$::jsonb, 'B', NULL, E'Two independent clauses are present: the first ends with "Earth" and the second begins with "His research." These clauses require a boundary that separates two complete sentences. A period after "Earth" followed by a capitalized "His" correctly separates the two independent clauses into two sentences. Using only a comma after "Earth" creates a comma splice, joining two independent clauses with just a comma, which violates Standard English conventions. Omitting all punctuation produces a run-on sentence. Using a semicolon followed by "and" is redundant; a semicolon already functions as a conjunction-level separator, so pairing it with a coordinating conjunction when no additional emphasis or list structure is present is nonstandard in this context.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E5BX5Y', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every summer, the municipal orchestra of Vilnius _______ a series of free concerts in the city''s public parks, drawing audiences from across Lithuania and neighboring countries.', $lyceon_json$[{"key":"A","text":"perform"},{"key":"B","text":"have performed"},{"key":"C","text":"performing"},{"key":"D","text":"performs"}]$lyceon_json$::jsonb, 'D', NULL, E'The subject of the sentence is "the municipal orchestra," a singular noun. A singular subject requires a singular verb form. "Performs" is the third-person singular present-tense form that agrees with "orchestra." "Perform" is a plural verb form that does not agree with the singular subject. "Have performed" introduces the present perfect tense with a plural auxiliary, conflicting with both the singular subject and the habitual present tense established by "Every summer." "Performing" is a participle, not a finite verb, and would leave the sentence without a main verb, creating a fragment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F0A6EN', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Yuto Nakamura found that deep-sea anglerfish in the Mariana Trench exhibit bioluminescent patterns distinct from those of anglerfish at shallower depths, leading him to hypothesize that extreme hydrostatic pressure drives unique adaptations in light-producing organs. _______ when Nakamura subjected shallow-water anglerfish to simulated high-pressure environments in laboratory tanks, the fish''s bioluminescent output did not shift toward the patterns observed in their deep-sea counterparts.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"As a result,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"However,"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct transition is "However," which signals that the laboratory results contradicted Nakamura''s hypothesis about hydrostatic pressure driving bioluminescent adaptations. The first sentence presents the hypothesis; the second sentence presents evidence that undermines it. "In addition," incorrectly implies the second sentence adds supporting information. "As a result," incorrectly implies a cause-and-effect relationship. "Specifically," incorrectly implies the second sentence elaborates on a detail from the first.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F2UUV5', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes a central tension in the text?', E'Linguist Priya Chandrasekaran has documented a paradox in the revitalization of Toda, a Dravidian language spoken by roughly 1,600 people in the Nilgiri Hills of southern India. Community elders, who are the most fluent speakers, insist that Toda should be taught exclusively through oral apprenticeship — the traditional method by which ceremonial songs, dairy-ritual chants, and kinship narratives have been transmitted for centuries. Younger activists, however, have developed a Roman-script orthography and a smartphone app that gamifies vocabulary acquisition, arguing that without written and digital tools the language cannot compete for the attention of children raised on Tamil and English media. Chandrasekaran notes that both camps share the goal of language survival but that the elders view the activists'' tools as a form of cultural distortion: codifying Toda in Roman script, they argue, strips words of the embodied context — gesture, melody, setting — that gives them meaning. The activists counter that an unwritten language with fewer than two hundred child speakers is already in crisis and that preserving context is meaningless if no one is left to supply it.', $lyceon_json$[{"key":"A","text":"Elders and younger activists disagree about whether Toda is endangered enough to warrant active revitalization efforts."},{"key":"B","text":"Both groups seek to preserve Toda but conflict over whether oral-only transmission or written and digital methods better serve that goal."},{"key":"C","text":"The elders believe Toda should adopt a Dravidian script rather than the Roman script favored by activists."},{"key":"D","text":"Chandrasekaran argues that neither the elders' nor the activists' approach is likely to succeed in preserving Toda."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes a shared goal — language survival — alongside a disagreement about method: elders favor oral apprenticeship while activists favor written and digital tools. The choice stating that elders and activists disagree about whether Toda is endangered misreads the text, which says both camps agree on the goal of survival. The choice about a Dravidian script is fabricated; the passage mentions only Roman script and oral tradition. The choice attributing a pessimistic conclusion to Chandrasekaran goes beyond the text, which presents Chandrasekaran as documenting the paradox rather than judging the likely outcome.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G78I6Z', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if included in the text, would most effectively support the claim about Okoye''s narrative strategy?', E'Nigerian novelist Adaeze Okoye''s 2021 book The Tidal Clock has been praised for its unconventional handling of chronology. Rather than presenting events in reverse or shuffled order — techniques associated with postmodern fiction — Okoye organizes her chapters around tidal cycles: events at high tide unfold in one temporal direction while events at low tide proceed in another. Literary scholars have argued that this strategy does more than create formal novelty; it embeds the rhythms of the Lagos Lagoon into the structure of the narrative itself, making the physical environment an organizing principle rather than mere setting.', $lyceon_json$[{"key":"A","text":"\"Okoye's tidal structure transforms the lagoon from a backdrop into the novel's temporal architecture, so that the reader experiences place and time as inseparable.\""},{"key":"B","text":"\"The Tidal Clock belongs to a growing tradition of Nigerian novels that foreground urban landscapes as sites of political contestation.\""},{"key":"C","text":"\"Okoye's prose style, with its long compound sentences and minimal paragraph breaks, mirrors the relentless flow of water through the lagoon channels.\""},{"key":"D","text":"\"While The Tidal Clock has attracted scholarly attention, its commercial sales in Nigeria have remained modest compared to those of Okoye's earlier works.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The claim is that Okoye''s tidal-cycle structure makes the physical environment an organizing principle rather than mere setting. The quotation describing the lagoon as transformed from backdrop into temporal architecture directly supports this claim by echoing the idea that place becomes a structural element. The quotation about political contestation discusses thematic content unrelated to narrative structure. The quotation about prose style and long sentences addresses sentence-level stylistics rather than the chapter-level chronological strategy the passage highlights. The quotation about commercial sales addresses reception rather than narrative technique.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GFJ66R', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from Pietrowicz''s study, if accurate, would most directly undermine the alternative explanation offered by Schultz?', E'Cognitive scientist Marta Pietrowicz investigated why experienced chess players occasionally make catastrophic blunders — moves so poor that even novices would avoid them. Pietrowicz proposed that these errors arise from "pattern hijacking": the expert''s highly trained pattern-recognition system identifies a familiar board configuration and triggers a memorized response, even when subtle differences in the current position make that response disastrous. Neuroscientist Rolf Schultz offered an alternative explanation, arguing that catastrophic blunders are simply the result of attentional fatigue — players in the late stages of long matches lose focus regardless of pattern recognition. Schultz predicted that blunder rates should correlate primarily with match duration rather than with the presence of near-match board configurations.', $lyceon_json$[{"key":"A","text":"Pietrowicz found that blunder rates were highest in games where near-match configurations appeared early — within the first 20 moves — and that match duration had no significant effect on blunder frequency."},{"key":"B","text":"Pietrowicz found that players who made catastrophic blunders reported feeling more fatigued than players who did not, confirming the subjective experience of tiredness."},{"key":"C","text":"Pietrowicz found that novice players made more total errors per game than experienced players across all match durations."},{"key":"D","text":"Pietrowicz found that catastrophic blunders occurred with equal frequency in rapid and classical time controls, suggesting that clock pressure alone does not explain the phenomenon."}]$lyceon_json$::jsonb, 'A', NULL, E'Schultz''s alternative explanation predicts that blunder rates correlate with match duration. A finding that blunders peaked when near-match configurations appeared early (not late) and that duration had no significant effect directly contradicts Schultz''s prediction, undermining his fatigue-based account. The finding about subjective fatigue would actually support Schultz rather than undermine him. The finding about novice error rates addresses a different population and does not speak to whether duration or pattern similarity drives expert blunders. The finding about equal blunder frequency across time controls addresses clock pressure, which is related to but distinct from Schultz''s specific claim about match duration and attentional fatigue — it only partially engages his argument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H3ZP5J', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeological evidence from the Liang Bua cave site on Flores indicates that Homo floresiensis used stone tools with a sophistication rivaling those of larger-brained hominins. _______ some paleoanthropologists caution that tool complexity alone does not establish cognitive equivalence, since similar implements can emerge from different cognitive strategies and motor traditions.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"Accordingly,"},{"key":"C","text":"However,"},{"key":"D","text":"For example,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "However," which introduces a counterpoint to the initial claim. The first sentence suggests that Homo floresiensis possessed tool-making abilities comparable to those of larger-brained species, implying a high level of cognition. The second sentence qualifies this by noting that similar tools can result from different cognitive processes, thereby challenging the inference of cognitive equivalence. "Moreover" would add supporting information, but the second sentence undermines rather than bolsters the implication of the first. "Accordingly" signals a logical consequence, yet the caution expressed is not a conclusion drawn from the initial evidence — it is a pushback against that evidence''s implications. "For example" would introduce a specific illustration of the preceding claim, but the second sentence introduces a general methodological objection rather than an example.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IU0B59', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Researchers at the Helmholtz Centre recently demonstrated that certain deep-sea microorganisms can metabolize polyethylene under high pressure. The finding has _______ implications for waste management, suggesting that biological degradation of plastics in ocean trenches may be more feasible than previously assumed.', $lyceon_json$[{"key":"A","text":"significant"},{"key":"B","text":"token"},{"key":"C","text":"redundant"},{"key":"D","text":"hostile"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a finding that changes the outlook on biological plastic degradation, so the blank requires a word meaning important or consequential. "Significant" correctly conveys that the implications are meaningful and noteworthy. "Token" means minimal or symbolic, which contradicts the passage''s emphasis on a genuine shift in feasibility. "Redundant" means unnecessary or superfluous, which makes no sense when describing implications of a new discovery. "Hostile" means antagonistic or unfriendly, which is nonsensical in this scientific context about waste management possibilities.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KORBRG', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'Coral reefs occupy less than one percent of the ocean floor, yet they support roughly a quarter of all marine species. This extraordinary concentration of biodiversity has led marine ecologists to label reefs "the rainforests of the sea." <u>However, rising ocean temperatures have triggered widespread coral bleaching events, threatening the survival of reef ecosystems worldwide.</u> In response, researchers are now experimenting with selective breeding programs designed to cultivate heat-tolerant coral strains.', $lyceon_json$[{"key":"A","text":"It introduces a threat that motivates the research efforts described afterward."},{"key":"B","text":"It provides statistical evidence supporting the comparison made in the previous sentence."},{"key":"C","text":"It defines a technical term that is essential for understanding the rest of the passage."},{"key":"D","text":"It summarizes the main finding of the selective breeding programs."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence shifts the passage from describing the ecological importance of coral reefs to identifying the danger they face from rising temperatures. This danger then directly motivates the research described in the final sentence, so the underlined sentence functions as the bridge between the problem and the response. The claim that the sentence provides statistical evidence for the "rainforests of the sea" comparison is wrong because the underlined sentence contains no statistics and addresses a different topic — bleaching, not biodiversity density. The claim that it defines a technical term is wrong because while "coral bleaching" appears, the sentence does not define it; it describes a consequence of rising temperatures. The claim that it summarizes the breeding programs'' findings is wrong because the breeding programs are introduced only in the sentence that follows, and no findings are reported.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LQLIK3', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Tromsø have long studied how Arctic foxes survive extreme cold. In a 2023 study, biologist Karin Eldegard and her team tracked 37 Arctic foxes across northern Norway using GPS collars over two winters. They found that rather than seeking deep burrows during blizzards, the foxes frequently moved to exposed ridgelines where wind had swept away loose snow. There, the foxes could access frozen vegetation and cached prey items beneath a thin ice crust. Eldegard concluded that the foxes'' counterintuitive preference for windswept terrain during storms reflects a foraging strategy rather than a shelter-seeking behavior.', $lyceon_json$[{"key":"A","text":"Arctic foxes tracked in northern Norway during blizzards tended to seek windswept ridgelines for foraging rather than sheltering in deep burrows."},{"key":"B","text":"GPS collar technology has transformed how biologists study Arctic fox movement patterns in extreme winter conditions."},{"key":"C","text":"Arctic foxes in northern Norway rely exclusively on cached prey items to survive winter storms."},{"key":"D","text":"Karin Eldegard's research demonstrated that Arctic fox populations in northern Norway have declined due to severe blizzards."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on a finding that Arctic foxes move to windswept ridgelines during blizzards to forage, not to shelter, making the choice about foraging on windswept terrain the main idea. The choice about GPS collar technology mentions a detail from the methodology but does not capture the central finding. The choice claiming foxes rely exclusively on cached prey overstates the passage, which mentions both frozen vegetation and cached prey. The choice about population decline introduces a claim not present in the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OCYA2J', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely respond to the conclusion drawn in Text 2?', E'Text 1: Archaeologist Nadia Petrov has proposed that the sudden appearance of large-scale grain storage facilities in Mesopotamia around 7500 BCE indicates a deliberate, top-down reorganization of food distribution. Petrov argues that these facilities required centralized planning because their uniform architectural design across distant settlements implies coordination by an authority capable of imposing standardized construction practices.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PLMSL7', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'During the 1970s, ethnobotanist Wanda Pratt spent months living among the Asháninka people of _______ understanding of over two hundred medicinal plants used by the community was informed not only by laboratory analysis but also by the oral traditions that elders shared with her during evening ceremonies.', $lyceon_json$[{"key":"A","text":"Peru. Her"},{"key":"B","text":"Peru, her"},{"key":"C","text":"Peru; and her"},{"key":"D","text":"Peru her"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contains two independent clauses. The first describes Pratt''s fieldwork and ends with "Peru." The second begins with "Her understanding" and contains its own subject and predicate. A period after "Peru" correctly separates these independent clauses into two sentences. A comma after "Peru" creates a comma splice between two independent clauses. A semicolon followed by "and" is redundant and nonstandard; a semicolon already serves as a boundary equivalent to a period and should not be paired with a coordinating conjunction in this structure. Omitting punctuation entirely produces a run-on sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ROTALU', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Entomologist Karla Espinoza has documented over 370 species of beetles in the cloud forests of central Ecuador. _______ her cataloging efforts have already led to the identification of 19 previously unknown species, suggesting that the region''s biodiversity has been significantly underestimated.', $lyceon_json$[{"key":"A","text":"In fact,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "In fact," which introduces a specific detail that reinforces and intensifies the preceding claim about Espinoza''s documentation work. "By contrast" incorrectly signals a comparison between opposing ideas, but the second sentence supports rather than contrasts with the first. "Nevertheless" implies a concession or unexpected outcome, yet the discovery of new species is a natural extension of cataloging work, not a surprising counterpoint. "In other words" suggests a restatement, but the second sentence provides new, additional information rather than rephrasing the first.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S7SFYH', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Linguist Helena Marques has argued that the global spread of English is primarily beneficial for non-native speakers because it provides access to international commerce, scientific literature, and diplomatic forums. She contends that the economic advantages of English fluency far outweigh any cultural costs associated with learning it.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SPTVLC', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing a report for a general audience, a student wants to introduce the significance of Mariam al-Asturlabi''s contribution to astronomy. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TEQJA2', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'The 1923 Kantō earthquake devastated Tokyo''s infrastructure, but it also _______ an ambitious urban redesign: city planners widened boulevards, installed modern sewage systems, and established firebreaks that would shape the capital''s layout for the next century.', $lyceon_json$[{"key":"A","text":"precipitated"},{"key":"B","text":"forfeited"},{"key":"C","text":"obscured"},{"key":"D","text":"depleted"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence states that the earthquake, while destructive, also triggered a large-scale urban redesign. "Precipitated" means caused to happen suddenly or brought about, which fits the idea that the disaster served as the catalyst for planned reconstruction. "Forfeited" means gave up or surrendered something one possessed, which is illogical because the earthquake did not voluntarily relinquish a redesign. "Obscured" means concealed or made unclear, which contradicts the passage''s point that the redesign was a visible, deliberate consequence. "Depleted" means exhausted or used up a supply, which is nonsensical when the object is an ambitious redesign plan rather than a consumable resource.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TRIJWO', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the two texts characterize urban green spaces?', E'Text 1: Urban planner Miriam Okafor argues that converting vacant lots into community gardens yields measurable public health improvements. In a 2023 longitudinal study of 47 neighborhoods in Lagos, she found that residents living within 300 meters of a community garden reported 19 percent fewer stress-related medical visits over a three-year period compared to matched control neighborhoods without gardens.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VDUHTS', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Anika Patel recently cataloged seventeen previously undocumented species of nudibranchs along the coast of Mozambique. Her _______ has reshaped scientific understanding of invertebrate biodiversity in the western Indian Ocean.', $lyceon_json$[{"key":"A","text":"research, which spanned nearly four years,"},{"key":"B","text":"research which spanned nearly four years"},{"key":"C","text":"research. Which spanned nearly four years,"},{"key":"D","text":"research which spanned nearly four years,"}]$lyceon_json$::jsonb, 'A', NULL, E'The nonrestrictive relative clause "which spanned nearly four years" provides additional but nonessential information about Patel''s research and must be set off by commas on both sides. The choice "research, which spanned nearly four years," correctly places commas before and after the clause. Omitting both commas treats the clause as restrictive, implying there were multiple research projects and only one spanned four years, which is unsupported by the passage. Placing a period before "Which" creates a sentence fragment beginning with a relative pronoun. Omitting only the first comma while retaining the second produces an inconsistent punctuation pattern that violates Standard English conventions for nonrestrictive clauses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X8W5RG', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1847, Ignaz Semmelweis observed that the mortality rate in a maternity ward staffed by medical students was nearly five times higher than in a ward staffed by midwives. He hypothesized that "cadaverous particles" carried on students'' hands from autopsy rooms caused the infections. When he instituted mandatory hand-washing with a chlorinated lime solution, the mortality rate in the students'' ward fell to levels comparable to the midwives'' ward. Despite this dramatic evidence, Semmelweis''s colleagues largely dismissed his findings, and the germ theory of disease would not gain broad acceptance for another two decades.', $lyceon_json$[{"key":"A","text":"It presents an observation, proposes an explanation, describes a successful intervention, and then notes the intervention's initial rejection."},{"key":"B","text":"It compares two competing scientific theories and evaluates which one was ultimately supported by experimental data."},{"key":"C","text":"It narrates a researcher's career chronologically, from early training through major publications to eventual recognition."},{"key":"D","text":"It describes a medical controversy and then argues that one side was ethically superior to the other."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage follows a clear four-part structure: Semmelweis''s observation of differing mortality rates, his hypothesis about cadaverous particles, the successful result of his hand-washing intervention, and the rejection of his findings by contemporaries. The claim that the text compares two competing theories is wrong because only Semmelweis''s hypothesis is presented; no rival theory is discussed or evaluated. The claim that it narrates a full career chronology is wrong because the passage focuses on a single episode and mentions neither Semmelweis''s training nor any publications. The claim that it argues for one side''s ethical superiority is wrong because the passage reports events without making an ethical judgment about the colleagues who dismissed the findings.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XAEF8N', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Historian Tomás Requena examined municipal tax records from the Spanish colonial port of Veracruz between 1731 and 1758. He found that the volume of cacao beans arriving at Veracruz from Tabasco province remained roughly constant over the period, yet the tax revenue collected on cacao shipments fell by nearly 40 percent. Requena ruled out changes in the tax rate, which colonial records confirm was fixed at 6 percent ad valorem throughout the period. He also confirmed that no competing port diverted Tabasco''s cacao trade during these decades. Requena therefore concluded that the decline in tax revenue most likely resulted from ________', $lyceon_json$[{"key":"A","text":"a sustained drop in the market price of cacao beans at Veracruz, which reduced the taxable value of each shipment even though volume remained stable."},{"key":"B","text":"an increase in the proportion of cacao consumed domestically in Tabasco before it could be shipped to Veracruz for taxation."},{"key":"C","text":"a shift in Spanish colonial trade policy that redirected Veracruz cacao exports away from European markets and toward Caribbean islands."},{"key":"D","text":"widespread spoilage of cacao beans during ocean transport, which caused merchants to discard a significant fraction of each shipment before it reached port."}]$lyceon_json$::jsonb, 'A', NULL, E'The tax was ad valorem (based on value), the rate was fixed, and volume was constant. The only remaining variable that could reduce revenue is the price per unit, so a sustained price drop is the logical inference. The choice about domestic consumption in Tabasco contradicts the passage''s finding that the volume arriving at Veracruz remained constant. The choice about redirected exports introduces a trade-policy shift not mentioned in the passage and would not directly explain reduced tax revenue at Veracruz if volume there was stable. The choice about spoilage contradicts the stated constancy of arriving volume — if significant quantities were discarded before reaching port, the recorded volume would have declined.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XRFUKN', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason Vasquez gives for the unexpected resilience of terracotta facades in earthquake-prone regions?', E'Architectural historian Elena Vasquez has challenged the assumption that terracotta cladding is inherently fragile in seismic zones. Studying 143 terracotta-clad buildings that survived major earthquakes in Chile between 1939 and 2010, Vasquez found that the material''s slight flexibility — it can deform up to 0.7 millimeters per tile without cracking — allows facades to absorb lateral forces that would shatter rigid stone or concrete panels. Moreover, the hollow-core design common in early twentieth-century terracotta tiles reduces overall facade weight, lessening the inertial load on structural frames during ground motion. Vasquez argues that this combination of micro-flexibility and low mass, rather than any reinforcement technique, explains why so many terracotta facades remained intact while adjacent stone cladding failed.', $lyceon_json$[{"key":"A","text":"Terracotta tiles were typically attached with a specialized mortar that absorbed seismic vibrations before they reached the building frame."},{"key":"B","text":"The combination of slight deformability in individual tiles and the low weight of hollow-core terracotta reduces seismic damage."},{"key":"C","text":"Terracotta cladding was used primarily on steel-frame buildings that were themselves more earthquake-resistant than concrete structures."},{"key":"D","text":"Chilean building codes after 1939 required terracotta facades to include hidden steel reinforcement strips within each tile."}]$lyceon_json$::jsonb, 'B', NULL, E'Vasquez explicitly attributes terracotta''s resilience to two factors: micro-flexibility (deformation up to 0.7 mm without cracking) and the low mass of hollow-core tiles, which together reduce seismic damage. The choice about specialized mortar introduces a claim absent from the passage. The choice about steel-frame buildings infers a structural explanation the passage does not make. The choice about hidden steel reinforcement contradicts the passage, which states that the resilience comes from inherent material properties rather than any reinforcement technique.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
